<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {NativeSelect,AdvancedFilters,HelpTip,useHostContext} from '@openclaw-plugins/control-ui-kit';
import {currentUiTarget} from '../../agent-repo-api/ui-navigation.mjs';
import {useManagementRequest} from './management-request';
import PeopleManager from './PeopleManager.vue';
const draftMapping=ref(''),draftMissing=ref('');
const props=defineProps<{agentId?:string;embedded?:boolean}>();
const context=useHostContext(),group=ref(''),mapping=ref(''),missing=ref(''),stats=ref<{total:number;stats?:{giteaSources?:Record<string,number>;missing?:Record<string,number>}}>();
const agentId=computed(()=>props.agentId??currentUiTarget({...context.value,props:{agentId:context.value.props.agentId}}).agentId??'');
const safe=(v:unknown)=>context.value.host.redact(String(v??''));
const groups=computed(()=>(context.value.host.sessions.rows??[]).filter(row=>row.key?.startsWith('agent:'+agentId.value+':feishu:group:oc_')));
const filters=computed(()=>({...mapping.value?{giteaSource:mapping.value}:{},...missing.value?{missing:missing.value}:{}}));
const request=useManagementRequest(context,()=>agentId.value,'agent-repo','projects-',action=>['peopleSyncInfo','syncPeople'].includes(action)?group.value:'agent:'+agentId.value+':agent-repo-people');
const scope=computed(()=>[agentId.value,group.value,context.value.presented,context.value.host.connection.canRead,context.value.host.connection.canWrite].join('|'));
watch(agentId,()=>{group.value='';stats.value=undefined;mapping.value='';missing.value='';},{flush:'sync'});
watch(groups,rows=>{if(!rows.some(row=>row.key===group.value))group.value='';});
watch(group,()=>{request.invalidate();stats.value=undefined;},{flush:'sync'});
function selectAgent(value:unknown){const id=String(value);context.value.host.agents.select(id);if(context.value.props.agentId)context.value.host.navigation.openPage({id:'people',params:{agentId:id}});}
</script>
<template><section class="ar-people-page" aria-label="Agent 人员库管理"><header class="ar-people-page-header"><div><component :is="(props.embedded||context.props.embeddedManagement)?'h2':'h1'">飞书人员管理</component><p>统一管理此 Agent 在全部会话中认识的人员，飞书同步和聊天采集使用同一份资料。</p></div><HelpTip title="人员资料说明"><p>聊天自动采集真实发送者和原生提及人。批量同步请选择已有群聊；人工更正优先保留。身份与账号关联不改变业务操作权限。</p></HelpTip><NativeSelect v-if="!(props.embedded||context.props.embeddedManagement)" :model-value="agentId" aria-label="人员库所属 Agent" @update:model-value="selectAgent"><option v-for="agent in context.host.agents.rows" :key="agent.id" :value="agent.id">{{safe(agent.name??agent.id)}}</option><option v-if="agentId&&!(context.host.agents.rows??[]).some(a=>a.id===agentId)" :value="agentId">{{safe(agentId)}}</option></NativeSelect></header><template v-if="context.presented"><p v-if="!context.host.connection.canRead" class="ar-error">需要 operator.read 权限才能查看人员库。</p><p v-else-if="!agentId">请先选择一个 Agent。</p><template v-else><p class="ar-people-page-scope">{{safe('当前 Agent：'+agentId+' · 跨会话统一管理 · 与其他 Agent 隔离')}}</p><div class="ar-people-stats" aria-label="人员库统计"><div v-for="[label,value] in [['匹配人员',stats?.total??'—'],['已确认关联',stats?.stats?.giteaSources?.admin??0],['待核验关联',stats?.stats?.giteaSources?.email_prefix??0],['缺少邮箱',stats?.stats?.missing?.email??0]]" :key="label"><strong>{{value}}</strong><span>{{label}}</span></div></div><div class="ar-people-page-controls"><AdvancedFilters :session-scoped="false" title="人员筛选" :count="Number(!!mapping)+Number(!!missing)" @open="draftMapping=mapping;draftMissing=missing" @apply="mapping=draftMapping;missing=draftMissing" @reset="draftMapping='';draftMissing=''"><label><span>账号关联状态</span><NativeSelect v-model="draftMapping" aria-label="账号关联状态"><option value="">全部关联状态</option><option value="admin">人工确认</option><option value="email_prefix">邮箱推导待核验</option><option value="unknown">未关联</option></NativeSelect></label><label><span>资料完整度</span><NativeSelect v-model="draftMissing" aria-label="资料完整度"><option value="">全部资料</option><option v-for="[key,label] in [['name','缺少姓名'],['email','缺少邮箱'],['departments','缺少部门'],['giteaUsername','缺少 Gitea 账号']]" :key="key" :value="key">{{label}}</option></NativeSelect></label></AdvancedFilters><label><span>飞书同步来源</span><NativeSelect v-model="group" aria-label="飞书同步来源"><option value="">选择已有群聊以同步成员</option><option v-for="row in groups" :key="row.key" :value="row.key">{{safe(row.label??row.displayName??row.key.split(':feishu:group:')[1])}}</option></NativeSelect></label></div><div class="ar-people-page-body"><PeopleManager :key="scope" inline :invoke="request.invoke" :safe="safe" :can-write="context.host.connection.canWrite===true" :is-group="!!group" :filters="filters" @loaded="stats=$event"/></div></template></template></section></template>
